// 第1章（青年期 19〜22歳）シナリオデータ
// step の書式:
// {sp:"narr"|"me"|キャストid, t:"本文"} … 地の文・セリフ（{style}=主・流儀名、{sig}=看板技名に置換される）
// 流派別用語（第38節）: {exam}=審査名、{proof}=認定の証、{rank}=地位、{who}=証を持つ人の呼称、{young}=若手の二つ名、{nickname}=現在の二つ名。data-styles.js の styleTerms() が主・流儀ごとに解決する
// {img:"aizawa"} … 立ち絵表示の切り替え（nullで消去）
// {fx:{...}} … パラメータ変化（money/fatigue/sei/aku/attention/expMain/stat/dmg/flags/affection/meet/record）
// {choice:[{label, fx, say:[step...]}...]} … 選択肢。選んだ肢の say が続けて流れる
// {battle:BATTLE_ID, win:[step...], lose:[step...]} … 戦闘。勝敗で分岐
// {debate:DEBATE_ID} … SNS議論バトル
// {jump:"sceneId"} … 別シーンへ
// {week:true} … そのまま週間行動へ戻る

